import { sql } from "drizzle-orm";
import { bigint, check, index, integer, jsonb, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { app_user } from "./auth-schema";

// Relative imports only: drizzle-kit loads this file outside Next, where `@/` does not resolve.

// Better Auth's own tables (app_user, session, account, verification, rate_limit) are generated by
// `pnpm auth:schema` — never edit auth-schema.ts by hand.
export * from "./auth-schema";

// Per-account sign-in throttle, keyed by lower-cased email whether or not the account exists, so a
// locked-out unknown address behaves exactly like a real one (no enumeration). See lib/auth/lockout.ts.
export const loginAttempt = pgTable("login_attempt", {
  emailKey: text("email_key").primaryKey(),
  /** Consecutive failures since the last lock or success. */
  failures: integer("failures").notNull().default(0),
  /** How many times this address has been locked since its last success — drives the exponential back-off. */
  lockLevel: integer("lock_level").notNull().default(0),
  lockedUntil: timestamp("locked_until", { withTimezone: true }),
  lastFailureAt: timestamp("last_failure_at", { withTimezone: true }),
});

// Append-only (triggers in the audit_log_append_only migration). actor_id is NO ACTION: accounts are
// deactivated, never deleted. actor_label keeps who/what acted even for failed sign-ins and the CLI.
export const auditLog = pgTable(
  "audit_log",
  {
    id: bigint("id", { mode: "number" }).primaryKey().generatedAlwaysAsIdentity(),
    at: timestamp("at", { withTimezone: true }).notNull().defaultNow(),
    actorId: text("actor_id").references(() => app_user.id),
    actorLabel: text("actor_label").notNull(),
    action: text("action").notNull(),
    entityType: text("entity_type"),
    entityId: text("entity_id"),
    ip: text("ip"),
    userAgent: text("user_agent"),
    detail: jsonb("detail"),
  },
  (table) => [
    index("audit_log_at_idx").on(table.at.desc()),
    index("audit_log_actor_idx").on(table.actorId, table.at.desc()),
    index("audit_log_action_idx").on(table.action, table.at.desc()),
    check("audit_log_action_nonblank", sql`length(btrim(${table.action})) > 0`),
  ],
);
